CREATE TABLE `ts_codeql_configs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `repository_id` bigint unsigned NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `languages` json NOT NULL,
  `initial_languages` json NOT NULL,
  `workflow` text COLLATE utf8mb4_general_ci,
  `repository_grid` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `onboarded_by_actor_grid` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_by_actor_login` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `template_version` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `tag` tinyint unsigned DEFAULT NULL,
  `query_suite_type` json DEFAULT NULL,
  `threat_model` tinyint unsigned NOT NULL DEFAULT '0',
  `validation_run_status` tinyint unsigned DEFAULT NULL,
  `java_extraction_options` tinyint unsigned DEFAULT '0',
  `csharp_extraction_options` tinyint unsigned DEFAULT '0',
  `deprecated_at` datetime(6) DEFAULT NULL,
  `enabled_at` datetime(6) DEFAULT NULL,
  `using_combined_languages` boolean NOT NULL default false,
  `runner_label` varchar(256) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cpp_extraction_options` tinyint unsigned DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `index_codeql_configs_on_repository_id_tag` (`repository_id`,`tag`),
  KEY `index_codeql_configs_for_refresh_new` (`tag`,`updated_at`,`repository_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
